window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"9Mqooi_q9pQ","speaker":"Beate Meinl-Reisinger","role":"Federal Minister","country":"Austria","region":"Europe","url":"https://www.youtube.com/watch?v=9Mqooi_q9pQ","date":"20260925","title":"🇦🇹 Austria - Federal Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":767,"words":1553,"counts":{"claims":24,"promises":6,"attacks":0},"topics":[{"topic":"Autonomous weapons","share":0.1742,"seconds":134},{"topic":"Israel-Gaza","share":0.09,"seconds":69},{"topic":"UN Security Council","share":0.0878,"seconds":67},{"topic":"UN institutions","share":0.0857,"seconds":66},{"topic":"Russia Ukraine","share":0.0842,"seconds":65},{"topic":"UN effectiveness","share":0.0841,"seconds":64},{"topic":"International law","share":0.0817,"seconds":63},{"topic":"UN reform","share":0.0813,"seconds":62},{"topic":"IAEA","share":0.0802,"seconds":61},{"topic":"Austria dialogue","share":0.0793,"seconds":61},{"topic":"International rules","share":0.0715,"seconds":55}],"timeline":[[2,64,null],[66,131,"UN institutions"],[132,200,"UN Security Council"],[200,265,"Russia Ukraine"],[267,336,"Israel-Gaza"],[337,400,"International law"],[403,468,"UN effectiveness"],[469,532,"UN reform"],[533,605,"Autonomous weapons"],[606,668,"IAEA"],[669,731,"Autonomous weapons"],[733,793,"Austria dialogue"],[796,850,"International rules"]],"stances":{"UN institutions":"Beate Meinl-Reisinger states that global institutions are struggling to keep pace with conflicts and power shifts, emphasizing that the UN has historically ensured prosperity by binding power to agreed rules.","UN Security Council":"Beate Meinl-Reisinger states that Austria is a proud host country and successfully campaigned for a seat on the UN Security Council.","Russia Ukraine":"Beate Meinl-Reisinger states that Austria will not accept border changes by force and calls for an urgent ceasefire in the conflict.","Israel-Gaza":"Beate Meinl-Reisinger states that neither side can achieve peace through bombing, calls for a two-state solution while rejecting settlement expansions, and demands the disarmament of Hamas and withdrawal of the IDF from Gaza.","International law":"Beate Meinl-Reisinger argues that international rules must apply universally to protect civilians and ensure accountability for violations.","UN effectiveness":"Beate Meinl-Reisinger argues that the United Nations is failing to solve conflicts and deliver aid because member states have allowed it to stagnate, despite there being no alternative to the organization.","UN reform":"Beate Meinl-Reisinger states that Austria supports the Secretary General's reform efforts and is committed to making Security Council decisions more inclusive as an incoming member.","Autonomous weapons":"Beate Meinl-Reisinger argues that machines should not have the authority to decide on taking human lives and calls for international rules prohibiting this.","IAEA":"Beate Meinl-Reisinger highlights the historical success of the IAEA in establishing rules for peaceful nuclear use and argues that similar proactive measures are needed for artificial intelligence.","Austria dialogue":"Beate Meinl-Reisinger asserts that Austria will maintain open channels for dialogue to prevent violence and emphasizes that human rights are a current responsibility rather than settled history.","International rules":"Beate Meinl-Reisinger argues that power must be subject to rules and technology must remain under human responsibility."},"claims":[{"t":111,"quote":"For more than 80 years, this organization has stood for one answer.","topic":"UN institutions","kind":"fact"},{"t":119,"quote":"That answer secured Austria's and our prosperity. It still does.","topic":"UN institutions","kind":"fact"},{"t":126,"quote":"We are a nation of 9 million people, an open liberal democracy, and we are proud of it.","topic":"UN institutions","kind":"number"},{"t":167,"quote":"In Austria, we are fortunate to live in peace, but the consequences reach us. Energy prices rise, factories close, and families are forced to flee war and seek safety across Europe.","topic":"UN Security Council","kind":"fact"},{"t":185,"quote":"This is why we are a proud host country of the organization, why we successfully campaigned for a seat on the UN Security","topic":"UN Security Council","kind":"self_credit"},{"t":239,"quote":"For more than 4 years, Russia's war of aggression against Ukraine has violated the UN Charter, and it still does.","topic":"Russia Ukraine","kind":"fact"},{"t":247,"quote":"During my last visit to to Kyiv, I witnessed the pain it causes firsthand.","topic":"Russia Ukraine","kind":"self_credit"},{"t":272,"quote":"After years of bloodshed and suffering, it is obvious no one can bomb their way to peace.","topic":"Israel-Gaza","kind":"fact"},{"t":301,"quote":"Any unilateral actions that undermine this prospect, including the continued settlement expansions in the West Bank, only perpetuate the conflict and must be firmly rejected by all of us.","topic":"Israel-Gaza","kind":"fact"},{"t":348,"quote":"In Lebanon, we need a sustainable arrangement to support the Lebanese armed forces in disarming Hezbollah.","topic":"International law","kind":"fact"},{"t":355,"quote":"The withdrawal of UNIFIL must not create a vacuum that will leave the region worse off than before.","topic":"International law","kind":"fact"},{"t":410,"quote":"Today, the United Nations too often falls short. Not because it has failed, because we have let it stand still.","topic":"UN effectiveness","kind":"fact"},{"t":428,"quote":"The United Nations was not created to discuss international problems. It was created to solve them.","topic":"UN effectiveness","kind":"fact"},{"t":480,"quote":"Austria has been a strong supporter of the reform efforts of the Secretary General.","topic":"UN reform","kind":"fact"},{"t":516,"quote":"One of the most urgent threats today is the loss of human control over weapons.","topic":"UN reform","kind":"fact"},{"t":533,"quote":"This killer robot was played by a famous Austrian-born Arnold Schwarzenegger. In the movies, Skynet learns to choose its own targets and starts a war.","topic":"Autonomous weapons","kind":"fact"},{"t":554,"quote":"Today, weapons with increasing autonomy are already used on the battlefield.","topic":"Autonomous weapons","kind":"fact"},{"t":636,"quote":"In 1955, Austria was free again. Two years later, the IAEA began its work and Vienna became its home.","topic":"IAEA","kind":"fact"},{"t":645,"quote":"The world did not ban atomic energy. It built rules for its peaceful use, but those rules came only after Hiroshima and Nagasaki had shown the terrible cost of waiting.","topic":"IAEA","kind":"fact"},{"t":669,"quote":"For this reason, Austria joins the UN Secretary General and the President of the ICRC in calling for a legally binding instrument with clear prohibitions and restrictions on autonomous weapons.","topic":"Autonomous weapons","kind":"fact"},{"t":705,"quote":"During our Security Council term, Austria will make emerging technologies, the protection of civilians, children in armed conflict, and women's full participation peace processes priorities.","topic":"Autonomous weapons","kind":"self_credit"},{"t":744,"quote":"During the Cold War, states that deeply distrusted one another still met in Vienna.","topic":"Austria dialogue","kind":"fact"},{"t":756,"quote":"In Vienna in 1993, the United Nations affirmed that those rights belong to every person everywhere.","topic":"Austria dialogue","kind":"fact"},{"t":796,"quote":"There are 193 countries in this hall.","topic":"International rules","kind":"number"}],"promises":[{"t":200,"quote":"Austria will be a reliable partner in the Security Council during the next 2 years.","topic":"Russia Ukraine","kind":"promise"},{"t":256,"quote":"We will not accept a change of borders by force.","topic":"Russia Ukraine","kind":"threat"},{"t":392,"quote":"This is why Austria will also continue to stand firm in protecting the International Court of Justice and the International Criminal Court.","topic":"International law","kind":"promise"},{"t":487,"quote":"we are committed to protect the principles of the charter to show the world that the council can act and to work towards making the decisions we take more inclusive.","topic":"UN reform","kind":"promise"},{"t":705,"quote":"During our Security Council term, Austria will make emerging technologies, the protection of civilians, children in armed conflict, and women's full participation peace processes priorities.","topic":"Autonomous weapons","kind":"promise"},{"t":749,"quote":"Austria will keep the door open whenever dialogue can prevent bloodshed.","topic":"Austria dialogue","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"I now give the floor to her Excellency Beata Meinl-Reisinger, Federal Minister for European and International Affairs of Austria. &gt;&gt; Mr. President, Mr. Secretary General, Your Excellencies, ladies and gentlemen, there are 193 countries represented in this hall At least I hope so still. 193 states that have signed up to the UN that have signed up to one essential that relations between states are not governed by sheer power, but by rules."},{"t":66,"topic":"UN institutions","text":"Today, this commitment is being tested by conflicts, by shifts in power, by new and our global institutions are struggling to keep pace. So, let me ask you a simple question that I believe sits underneath everything we are discussing this week. Who decides? Who decides whether a border is a line to be respected or a target to be crossed? Who decides whether a human being or a machine pulls a trigger? Who decides who gets hurt and who is left waiting outside the room? For more than 80 years, this organization has stood for one answer. Power must be bound by rules agreed That answer secured Austria's and our prosperity. It still does. We are a nation of 9 million people, an open liberal democracy, and we are proud of it."},{"t":132,"topic":"UN Security Council","text":"Alone, we cannot we cannot keep trade routes open, stabilize energy markets, or prevent wars. Like most countries in this hole, we depend [clears throat] on a world in which borders are respected, agreements are kept, and strength is bound by law. When that order weakens, the gravest price is paid by those least able to bear it. By countries already in crisis, by populations heavily dependent on food imports, and by people caught in In Austria, we are fortunate to live in peace, but the consequences reach us. Energy prices rise, factories close, and families are forced to flee war and seek safety across Europe. This is why the United Nations matters. It is our life insurance. This is why we are a proud host country of the organization, why we successfully campaigned for a seat on the UN Security I would like to thank you wholeheartedly for your support at the elections in June."},{"t":200,"topic":"Russia Ukraine","text":"Austria will be a reliable partner in the Security Council during the next 2 years. Austria, throughout the campaign, has made a promise to spare no effort on the Security Council to protect our common rules, to engage in dialogue with everyone, and to rebuild trust in our global order that has been eroded by a dangerous zero-sum logic. But for all of us, the road ahead is easy, because today that order is being tested in conflict after conflict. For more than 4 years, Russia's war of aggression against Ukraine has violated the UN Charter, and it still does. During my last visit to to Kyiv, I witnessed the pain it causes firsthand. Austria's position remains clear. We will not accept a change of borders by force. We need an urgent ceasefire to create a credible path to negotiations between the parties."},{"t":267,"topic":"Israel-Gaza","text":"In the Middle East, the continuous escalation teaches us a similar lesson. After years of bloodshed and suffering, it is obvious no one can bomb their way to peace. We want a prosperous and safe Israel. But the same applies to the Palestinians and to Israel's neighbors. Israelis and Palestinians deserve to live side by side in peace and security with a credible path to a two-state Any unilateral actions that undermine this prospect, including the continued settlement expansions in the West Bank, only perpetuate the conflict and must be firmly rejected by all of us. Palestinians in Gaza desperately need peace and stability with Hamas disarmed and the IDF withdrawing from the strip. Iran and the United States must come back to the negotiation table to end the suffering, to credibly revive the nuclear talks, and to stop holding global supply chains hostage to political ends."},{"t":337,"topic":"International law","text":"Especially when there are bilateral deadlocks and conflicts are impacting the whole world, I believe we believe we must pursue for multilateral solutions. In Lebanon, we need a sustainable arrangement to support the Lebanese armed forces in disarming Hezbollah. The withdrawal of UNIFIL must not create a vacuum that will leave the region worse off than before. The same set of international rules must protect civilians in Sudan, in the DRC, in Yemen, Haiti, Myanmar, Ethiopia, or other conflicts that receives far too little international International law must apply to all It must protect all civilians. And where violations occur, there must be responsibility and accountability. This is why Austria will also continue to stand firm in protecting the International Court of Justice and the International Criminal Court."},{"t":403,"topic":"UN effectiveness","text":"do not defend themselves. They need institutions capable of upholding them. Today, the United Nations too often falls short. Not because it has failed, because we have let it stand still. But, there is no alternative to the United Nations. There is only the work of making it work. The United Nations was not created to discuss international problems. It was created to solve them. Yet, as conflicts and injustice multiply, the UN too often fails to act. Inside this building, that failure can look like another meeting without a decision. Outside these walls, it means that wars continue, help does not arrive, and more families bury their dead. For these families, UN procedures do not What matters to them is whether food arrives, whether a doctor reaches them, whether peacekeepers protect them."},{"t":469,"topic":"UN reform","text":"Reform must therefore pass a simple test. Does it make the United Nations more able to deliver when people need Austria has been a strong supporter of the reform efforts of the Secretary General. And as an incoming member of the Security Council, we are committed to protect the principles of the charter to show the world that the council can act and to work towards making the decisions we take more inclusive. Because it matters who decides. The United Nations was built to confront the dangers of 1945. Today, we must face new and rapidly emerging dangers. One of the most urgent threats today is the loss of human control over weapons. Every Austrian and I believe maybe a lot of people here knows the Terminator movies about a machine sent to kill humans."},{"t":533,"topic":"Autonomous weapons","text":"This killer robot was played by a famous Austrian-born Arnold Schwarzenegger. In the movies, Skynet learns to choose its own targets and starts a war. Well, in 1984, this was science fiction. it is not fiction anymore. Today, weapons with increasing autonomy are already used on the battlefield. The direction's clear. Machines are gaining more freedom to find and strike But a machine cannot understand nor mercy. It cannot face a court or answer for a It must never have the final say over who lives and who dies. We therefore need international rules for autonomous weapons built around one clear principle, no machine may decide to take a human life. Some will say that agreement is impossible when technology moves so quickly and major powers distrust one History says otherwise."},{"t":606,"topic":"IAEA","text":"Imagine this hall in December 1953. Austria was still occupied while the superpowers were testing hydrogen bombs. And yet from this podium, Eisenhower named two things that did not yet exist. Negotiations to restore Austria's independence and an international agency that would would bring nuclear technology under international oversight to serve as Eisenhower said, the needs rather than the fears of mankind. In 1955, Austria was free again. Two years later, the IAEA began its work and Vienna became its home. The world did not ban atomic energy. It built rules for its peaceful use, but those rules came only after Hiroshima and Nagasaki had shown the terrible cost of waiting. We cannot afford to wait for a catastrophe to happen. With artificial intelligence, we can still act first."},{"t":669,"topic":"Autonomous weapons","text":"For this reason, Austria joins the UN Secretary General and the President of the ICRC in calling for a legally binding instrument with clear prohibitions and restrictions on autonomous weapons. Voluntary guidelines are not enough. We need binding rules that keep human beings in control and ensure And we must not drag this out. Mr. President, every rule and reform I've spoken about serves one purpose, During our Security Council term, Austria will make emerging technologies, the protection of civilians, children in armed conflict, and women's full participation peace processes priorities. Children must never be treated as collateral damage. Women must have a real voice at the negotiating table as leaders and peacebuilders, not as an afterthought."},{"t":733,"topic":"Austria dialogue","text":"Peace also requires dialogue. Dialogue is not and will never be weakness. It is the refusal to give violence the last word. During the Cold War, states that deeply distrusted one another still met in Vienna. Austria will keep the door open whenever dialogue can prevent bloodshed. And peace rests on human rights. In Vienna in 1993, the United Nations affirmed that those rights belong to every person everywhere. That principle is not settled history. It is a responsibility we must defend today. Ladies and gentlemen, I began by asking who decides. Let me end with our Austria's answer. The strongest voice in the room must not decide alone. Neither should the fastest algorithm, nor should those the with the most or the deepest pockets."},{"t":796,"topic":"International rules","text":"There are 193 countries in this hall. Most of us cannot impose our will on others. Most of us do not want to live in a world where some can. Power must answer to rules. Technology must remain under human Responsibility must always be owned by us, by humans. And ultimately, nations must speak so weapons remain silent. This is Austria's I thank you very much. &gt;&gt; We thank the Federal Minister for European and International Affairs of"}],"compare":[{"topic":"UN & its reform","share":0.3389,"mean":0.2041,"rank":33,"others":170},{"topic":"Artificial Intelligence","share":0.1742,"mean":0.0498,"rank":14,"others":83},{"topic":"International Law & Order","share":0.1532,"mean":0.0599,"rank":25,"others":102},{"topic":"Israel–Palestine","share":0.09,"mean":0.0522,"rank":42,"others":76},{"topic":"Russia-Ukraine War","share":0.0842,"mean":0.0351,"rank":29,"others":44},{"topic":"Nuclear Disarmament","share":0.0802,"mean":0.0037,"rank":3,"others":9}]};
